{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "DX-9065a's very low human F (2–3%) is explicitly attributed to its strong basic amidino groups; the query has no such strongly basic amidines, so this low-F mechanism is not transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Melagatran's oral F was only 0.9% after food intake, reflecting its polar zwitterionic structure; the query is far less polar and not zwitterionic, so the fed-state low-F result does not apply.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "BMS-187745 had F 2.6% as an oral solution, a value associated with its phosphonic acid group; the query lacks any phosphonate or strongly acidic functionality.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Olcegepant has F <1% and is a large peptide-like CGRP antagonist; the query is a smaller, more conventional oral drug-like molecule without that peptide-like polar surface.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although all retrieved human F records are low, they arise from molecules with strong basic amidines, zwitterionic/phosphonate polarity, or peptide-like size that are absent in the query. The query is a moderately lipophilic, non-extremely ionized small molecule (acalabrutinib-like BTK inhibitor) expected to have F >=20%, especially under fed conditions where exposure is increased.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query in the provided evidence.",
    "No structurally close analogue with measured F in the evidence set.",
    "Fed-state effect for the query is inferred from known food-effect direction, not directly evidenced here."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

